export interface PublicHoliday {
  date: string
  name: string
}

/** The region's holidays from `from` to `to` (YYYY-MM-DD, both included), in date order. */
export function holidaysFor(region: string, from: string, to: string): PublicHoliday[] {
  const out: PublicHoliday[] = []
  for (const rows of Object.values(HOLIDAYS)) {
    for (const [date, name, regions] of rows) {
      if (date < from || date > to) continue
      if (regions !== '*' && !regions.split(' ').includes(region)) continue
      out.push({ date, name })
    }
  }
  return out.sort((a, b) => a.date.localeCompare(b.date))
}

/** The years this table knows. */
export const HOLIDAY_YEARS = Object.keys(HOLIDAYS).map(Number).sort()

/** The last day the table covers: holidays after it are not known yet. */
export const HOLIDAYS_KNOWN_THROUGH = `${HOLIDAY_YEARS[HOLIDAY_YEARS.length - 1]}-12-31`
